Q: Get audio metadata (e.g. artist, album, №), HTML A: <p>I wrote a module for that purpose: <a href="https://github.com/Borewit/music-metadata" rel="nofollow noreferrer">music-metadata</a>:</p>
<p>Here is a demonstration of client side audio metadata extraction.
All you have to do, is provide it with an audio file with metadata set.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// import { parseBlob } from 'music-metadata';

async function run() {
    // We load music-metadata from a CDN in this snippet
    const {parseBlob} = await import('https://cdn.jsdelivr.net/npm/music-metadata@11.12.1/+esm');

    const doc = {};
    ['file', 'output', 'covers'].forEach(id =&gt; doc[id] = document.getElementById(id));

    doc.file.addEventListener('change', async (event) =&gt; {
        const file = event.target.files[0];
        if (file) {
            // Create a Blob URL for the audio element

            try {
                // Parse File (which is a Blob) using music-metadata
                doc.output.textContent = 'Extracting metadata...';
                const { common, format } = await parseBlob(file);

                // Display metadata
                const metadata = {
                    container: format.container || "?",
                    codec: format.codec || "?",
                    trackNr: common.track.no || "?",
                    title: common.title || "Unknown Title",
                    artist: common.artist || "Unknown Artist",
                    album: common.album || "Unknown Album",
                    albumartist: common.albumartist || "Unknown Album"
                };
                doc.output.textContent = JSON.stringify(metadata, null, 2);

                // Extract and display album art
                if (common.picture &amp;&amp; common.picture.length &gt; 0) {
                    common.picture.forEach((picture, index) =&gt; {
                        const base64String = btoa(String.fromCharCode(...new Uint8Array(picture.data)));
                        const imgElement = document.createElement('img');
                        imgElement.src = `data:${picture.format};base64,${base64String}`;
                        imgElement.alt = `Picture ${index + 1}`;
                        imgElement.style.maxWidth = '200px';
                        imgElement.style.margin = '10px';
                        doc.covers.append(imgElement);
                    });
                }
            } catch (err) {
                doc.output.textContent = 'Error parsing metadata: ' + err.message;
            }
        } else {
            doc.output.textContent = 'No file selected';
        }
    });
}

run();</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html&gt;
  &lt;head&gt;
    &lt;title&gt;Extract metadata with music-metadata&lt;/title&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;h3&gt;Select an audio file to extract metadata from&lt;/h3&gt;
    &lt;input style="cursor: pointer;" type="file" id="file" accept="audio/*" /&gt;
    &lt;pre id="output"&gt;&lt;/pre&gt;
    &lt;div id="covers"&gt;&lt;/div&gt;
  &lt;/body&gt;
&lt;/html&gt;</code></pre>
</div>
</div>
</p>
<p>I am the owner of the music-metadata project and the now obsolete music-metadata-browser project.</p>

Q: Change position of plotly hover box R A: <p><strong>TLDR:</strong></p>
<p>In Plotly.JS: Yes it is, see solution 1 and 2.</p>
<p>In Plotly-R: Yes, but with inprecise hover-hitboxes, see sol. 3.</p>
<h2>1. Fully customized tooltip</h2>
<p>Reusing some code from my answer <a href="https://stackoverflow.com/a/79521024/28479453">here</a> and <a href="https://stackoverflow.com/a/79503773/28479453">here</a>.</p>
<ul>
<li>Create your own <code>tooltip-div</code> style <code>custom-tooltip</code> using CSS. I took the CSS for the tooltip-triangle from <a href="https://css-tricks.com/the-little-triangle-in-the-tooltip/" rel="nofollow noreferrer">here</a>.</li>
<li>Whenever a point is hovered on, use the <a href="https://plotly.com/javascript/plotlyjs-events/#hover-event" rel="nofollow noreferrer"><code>plotly_onhover</code></a> event.</li>
<li>Within this event <code>e</code> there is information like which point was hovered on <code>e.points[0]</code> and the x-position of this point: <code>e.points[0].x</code>, y-position of this point: <code>e.points[0].y</code> but also <code>axis</code> details. We have to use <a href="https://community.plotly.com/t/how-to-customize-plotly-tooltip/332/16" rel="nofollow noreferrer"><code>yaxis.l2p</code></a>  from the y-axis in order to translate a y-position like <code>100</code> to the actual pixel-position <code>distX</code>. This is needed to place our <code>tooltip-div</code>!</li>
<li>To center the tooltip horizontally, we need to remove half of the tooltips' width, which is measured like <a href="https://johnkavanagh.co.uk/articles/element-dimensions-in-javascript-width-and-height/" rel="nofollow noreferrer"><code>tooltip?.clientWidth</code></a>: <code>tooltip.style.left = (distX - tooltip?.clientWidth / 2) + &quot;px&quot;;</code>.
Vertically we need to offset by <code>tooltip?.clientHeight - triangleHeight</code>.</li>
<li><code>tooltip.innerHTML = &quot;&lt;b&gt;Value: &quot; + pt.y + &quot;&lt;/b&gt;&quot;;</code> let's you define the content of the tooltip. Here you can basically use everything you want, tables, images, etc.</li>
<li><code>tooltip.style.display = &quot;block&quot;;</code> actually shows the tooltip only when hovered, when unhovered, we hide it again using <code>tooltip.style.display = &quot;none&quot;</code>.</li>
</ul>
<pre><code>library(plotly)
library(htmlwidgets) # for adding custom JS in onRender(JS)

js_code &lt;- '
function(el, x) {
  var style = document.createElement(&quot;style&quot;);
  style.innerHTML = `
    :root {
      --triangle-base: 7px;   /* base width of the triangle below */
      --triangle-height: 7px; /* height of the triangle below */
      --triangle-top: 100%;   /* vertical alignment in percent of tooltip height. &lt; 100 % --&gt; hides behind tooltip */
      --triangle-left: 50%;   /* horizontal alignment in percent of tooltip width 50 % --&gt; centered */

      --triangle-color: grey;
    }
    .custom-tooltip {
      display: none;
      position: absolute;
      background-color: white;
      border: 1px solid #ddd;
      color: black;
      padding: 2px 6px;
      border-radius: 4px;
      z-index: 1000;
      box-shadow: 2px 2px 6px rgba(0,0,0,0.2);
      font-family: Arial, sans-serif; 
      &amp;::before {
        content: &quot;&quot;;
        position: absolute;
        top: var(--triangle-top);
        left: var(--triangle-left);

        border-width: var(--triangle-base);
        border-style: solid;
        border-color: transparent;
        border-top: var(--triangle-height) solid var(--triangle-color);

        transform: translateX(-50%);
      }
    }
  `;
  document.head.appendChild(style);

  var tooltip = document.createElement(&quot;div&quot;);
  tooltip.className = &quot;custom-tooltip&quot;;
  document.body.appendChild(tooltip);

  el.on(&quot;plotly_hover&quot;, function(e) {
    var pt = e.points[0];
    var yaxis = pt.yaxis;
    var xaxis = pt.xaxis;

    var distY = yaxis.l2p(pt.y) + yaxis._offset;
    var distX = xaxis.l2p(pt.x) + xaxis._offset;
    var triangleHeight = parseInt(
      getComputedStyle(document.documentElement).getPropertyValue(&quot;--triangle-height&quot;)
    );

    tooltip.innerHTML = &quot;&lt;b&gt;Value: &quot; + pt.y + &quot;&lt;/b&gt;&quot;;
    tooltip.style.display = &quot;block&quot;;
    tooltip.style.left = (distX - tooltip?.clientWidth / 2) + &quot;px&quot;;
    tooltip.style.top  = (distY - tooltip?.clientHeight - triangleHeight) + &quot;px&quot;;
  });

  el.on(&quot;plotly_unhover&quot;, function(e) {
    tooltip.style.display = &quot;none&quot;; 
  });

  }
'

plotly::plot_ly(data = data.frame(x = 1:10, y = 1:10*10)) |&gt;
  plotly::add_trace(
    x = ~x, 
    y = ~y, 
    type = 'bar', 
    hoverinfo = 'skip', 
    text = ~y
  ) |&gt;
  htmlwidgets::onRender(js_code)
</code></pre>
<p><a href="https://i.sstatic.net/VC8nMoVt.gif" rel="nofollow noreferrer"><img src="https://i.sstatic.net/VC8nMoVt.gif" alt="plotly boxplot with custom hover-text above each bar" /></a></p>
<h2>2. Using tippy.js</h2>
<p>You can also use <a href="https://atomiks.github.io/tippyjs/" rel="nofollow noreferrer"><code>tippy</code></a>-script to add tooltips.</p>
<pre><code>library(plotly)
library(htmlwidgets)

js_code &lt;- '
function(el, x) {
  var div = document.createElement(&quot;div&quot;);
  div.style.cssText = &quot;position:absolute;width:1px;height:1px;pointer-events:none&quot;;
  document.body.appendChild(div);

  var tip = tippy(div, { content: &quot;&quot;, placement: &quot;top&quot;, arrow: true });

  el.on(&quot;plotly_hover&quot;, function(e) {
    var pt = e.points[0];
    var xaxis = pt.xaxis;
    var yaxis = pt.yaxis;

    div.style.left = xaxis.l2p(pt.x) + xaxis._offset + &quot;px&quot;;
    div.style.top  = yaxis.l2p(pt.y) + yaxis._offset + &quot;px&quot;;

    tip.setContent(&quot;Value: &quot; + pt.y);
    tip.show();
  });

  el.on(&quot;plotly_unhover&quot;, function(e) { tip.hide();});
}
'

plotly::plot_ly(data = data.frame(x = 1:10, y = 1:10*10)) |&gt;
  plotly::add_trace(x = ~x, y = ~y, type = &quot;bar&quot;, hoverinfo = &quot;skip&quot;, text = ~y) |&gt;
  htmlwidgets::onRender(js_code) |&gt;
  # add tippy-dependencies see https://github.com/atomiks/tippyjs?tab=readme-ov-file#cdn
  (\(x){x$dependencies &lt;- c(x$dependencies, list(
    htmltools::htmlDependency(
      &quot;tippy&quot;, &quot;6&quot;,
      src = c(href = &quot;https://unpkg.com&quot;),
      script = c(&quot;@popperjs/core@2&quot;, &quot;tippy.js@6&quot;)
    )
  ));x})()
</code></pre>
<p><a href="https://i.sstatic.net/826ECuuT.gif" rel="nofollow noreferrer"><img src="https://i.sstatic.net/826ECuuT.gif" alt="plotly boxplot with custom hover-text above each bar using tippy" /></a></p>
<h2>3. Native Solution (hacky and unclean)</h2>
<p>You can also overlay a scatter trace of a larger size and zero opacity with a slight offset to the left <code>x-0.2</code>. Beware that plotly still choses the closest bar, but will also do so when hovered over the bar and not exactly on it due to <a href="https://plotly.com/javascript/reference/layout/#layout-hovermode" rel="nofollow noreferrer">hovermode = &quot;x&quot;</a></p>
<blockquote>
<p>If &quot;x&quot; (or &quot;y&quot;), multiple hoverlabels will appear for multiple points at the &quot;closest&quot; x- (or y-) coordinate within the <code>hoverdistance</code>, with the caveat that no more than one hoverlabel will appear per trace. If &quot;x unified&quot; (or &quot;y unified&quot;), a single hoverlabel will appear multiple points at the closest x- (or y-) coordinate within the <code>hoverdistance</code> with the caveat that no more than one hoverlabel will appear per trace. In this mode, spikelines are enabled by default perpendicular to the specified axis</p>
</blockquote>
<pre><code>library(plotly)

plot_ly(data.frame(x = 1:10, y = 1:10 * 10)) |&gt;
  add_trace(
    x = ~ x,
    y = ~ y, # or for label slightly above bar ~ (y+2)
    type = &quot;bar&quot;,
    hoverinfo = &quot;none&quot;,
    showlegend = FALSE
  ) |&gt;
  add_trace(
    x = ~ (x - 0.2),
    y = ~ y,
    type = &quot;scatter&quot;,
    mode = &quot;markers&quot;,
    marker = list(opacity = 0, size = 8),
    hoverinfo = &quot;text&quot;,
    text = ~ paste0(&quot;y: &quot;, y),
    showlegend = FALSE
  ) |&gt;
  layout(
    hovermode = &quot;x&quot;,
    hoverlabel = list(bgcolor = &quot;white&quot;) # overwrite label background color
  )
</code></pre>
<p><a href="https://i.sstatic.net/Wv5P1RwX.gif" rel="nofollow noreferrer"><img src="https://i.sstatic.net/Wv5P1RwX.gif" alt="native" /></a></p>

Q: I have two same cIass name and one style is possible to apply style for first div class? A: <p>use <code>.circle:first-child</code> and you solve you problem</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-css lang-css prettyprint-override"><code>.circle:first-child {
  height: 100px;
  width: 100px;
  background: red;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div class="circle"&gt;First child&lt;/div&gt;
&lt;div class="circle"&gt;Second child&lt;/div&gt;</code></pre>
</div>
</div>
</p>

Q: how can I get the cover of an mp3 file? A: <p>I wrote code a snippet extracting album art of MP3 or audio files, based on <a href="https://github.com/Borewit/music-metadata" rel="nofollow noreferrer">music-metadata</a>, (which I am the repo owner of). Note that jsmediatags is abandoned since 4 years.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>async function run() {
    const mm = await import('https://cdn.jsdelivr.net/npm/music-metadata@11.12.1/+esm');

    const fileInput = document.getElementById('file');
    const output = document.getElementById('output');
    const title = document.getElementById('title');

    fileInput.addEventListener('change', async (event) =&gt; {
        const file = event.target.files[0];
        output.innerHTML = ''; // Clear previous output

        if (file) {
            try {
                // Parse metadata using music-metadata
                const { common } = await mm.parseBlob(file);

                title.textContent = `${common.title} has ${common.picture ? common.picture.length : 0} embedded images:`;

                // Extract and display album art
                if (common.picture &amp;&amp; common.picture.length &gt; 0) {
                    common.picture.forEach((picture, index) =&gt; {
                        const base64String = btoa(
                            String.fromCharCode(...new Uint8Array(picture.data))
                        );
                        const imgElement = document.createElement('img');
                        imgElement.src = `data:${picture.format};base64,${base64String}`;
                        imgElement.alt = `Picture ${index + 1}`;
                        imgElement.style.maxWidth = '200px';
                        imgElement.style.margin = '10px';
                        output.appendChild(imgElement);
                    });
                } else {
                    output.textContent = 'No album art found';
                }
            } catch (err) {
                output.textContent = 'Error parsing metadata: ' + err.message;
            }
        } else {
            output.textContent = 'No file selected';
        }
    });
}

run();</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
    &lt;meta charset="UTF-8" /&gt;
    &lt;title&gt;Extract Album Art with music-metadata&lt;/title&gt;
&lt;/head&gt;
&lt;body&gt;
    &lt;h3&gt;Select an audio file with embedded album art&lt;/h3&gt;
    &lt;input style="cursor: pointer;" type="file" id="file" accept="audio/*" /&gt;
    &lt;h3 id="title"&gt;&lt;/h3&gt;
    &lt;p id="output"&gt;&lt;/p&gt;
&lt;/body&gt;
&lt;/html&gt;</code></pre>
</div>
</div>
</p>
